import {existsSync,readFileSync,writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {registry} from '../src/registry.js';
import {pagePaths} from '../src/page-registry.js';

export function renderRegistryCounts(measurements=registry,pages=pagePaths){
  const sources=new Set(Object.values(measurements).map(item=>item.agency)).size;
  return [
    '# Registry counts',
    '',
    'Generated by `node scripts/update-registry-counts.mjs`. Do not edit by hand.',
    '',
    '| Registry item | Count | Definition |',
    '| --- | ---: | --- |',
    `| Measurements | ${Object.keys(measurements).length} | Keys in [src/registry.js](../src/registry.js). |`,
    `| Sources | ${sources} | Distinct measurement \`agency\` IDs; source channels, not a count of publishing institutions. |`,
    `| Pages | ${Object.keys(pages).length} | Keys in [src/page-registry.js](../src/page-registry.js); indicator is one page type. |`,
    '',
    'Economy family tabs, filters and individual series URLs do not add page types.',
    '',
  ].join('\n');
}

if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href){
  const output=new URL('../docs/registry-counts.md',import.meta.url),content=renderRegistryCounts();
  if(process.argv.includes('--check')){
    if(!existsSync(output)||readFileSync(output,'utf8')!==content){
      console.error('Registry counts are stale. Run node scripts/update-registry-counts.mjs.');
      process.exitCode=1;
    }
  }else writeFileSync(output,content);
}
